import { formatMoney } from "./format.ts";
import type { Customer } from "./price.ts";

export const LOYALTY_MIN_ORDERS = 5;

export interface Discounted {
  total: number;
  saved: number;
  message: string;
}

// More than five orders earns ten percent off. Amounts are whole cents.
export function applyLoyaltyDiscount(customer: Customer, total: number): Discounted {
  if (customer.orders <= LOYALTY_MIN_ORDERS) {
    return { total, saved: 0, message: "" };
  }
  const saved = Math.round(total / 10);
  return {
    total: total - saved,
    saved,
    message: `Loyalty discount: you saved ${formatMoney(saved)}`,
  };
}

