export interface Line {
  name: string;
  cents: number;
  quantity: number;
}

export interface Customer {
  id: string;
  orders: number;
}

export function lineTotal(line: Line): number {
  return line.cents * line.quantity;
}

export function orderTotal(lines: Line[]): number {
  return lines.reduce((sum, line) => sum + lineTotal(line), 0);
}

export interface DiscountedOrder {
  total: number;
  message: string;
}

export function loyaltyTotal(lines: Line[], customer: Customer): DiscountedOrder {
  const subtotal = orderTotal(lines);
  if (customer.orders <= 5) {
    return { total: subtotal, message: "No loyalty discount" };
  }
  const saved = Math.round(subtotal / 10);
  return { total: subtotal - saved, message: `Loyalty discount: you saved ${formatMoney(saved)}` };
}

