import { formatMoney } from "./money.ts";
import { orderTotal, type Customer, type Line } from "./price.ts";

export const LOYALTY_MIN_ORDERS = 5;
export const LOYALTY_PERCENT = 10;

export interface LoyaltyResult {
  total: number;
  saved: number;
  message: string;
}

// A customer with more than five orders gets ten percent off, rounded to the cent.
export function applyLoyalty(customer: Customer, lines: Line[]): LoyaltyResult {
  const full = orderTotal(lines);
  if (customer.orders <= LOYALTY_MIN_ORDERS) {
    return { total: full, saved: 0, message: "" };
  }
  const saved = Math.round((full * LOYALTY_PERCENT) / 100);
  return {
    total: full - saved,
    saved,
    message: `Loyalty discount: you saved ${formatMoney(saved)}`,
  };
}

