import { formatMoney } from "./money.ts";

export interface Line {
  name: string;
  cents: number;
  quantity: number;
}

export interface Customer {
  id: string;
  orders: number;
}

export function lineTotal(line: Line): number {
  return line.cents * line.quantity;
}

export function orderTotal(lines: Line[]): number {
  return lines.reduce((sum, line) => sum + lineTotal(line), 0);
}

export const LOYALTY_MIN_ORDERS = 5;

export interface Discounted {
  total: number;
  saved: number;
  message: string;
}

// More than five past orders earns ten percent off, rounded to the nearest cent.
export function loyaltyDiscount(customer: Customer, lines: Line[]): Discounted {
  const full = orderTotal(lines);
  if (customer.orders <= LOYALTY_MIN_ORDERS) {
    return { total: full, saved: 0, message: "No loyalty discount" };
  }
  const saved = Math.round(full / 10);
  return { total: full - saved, saved, message: `Loyalty discount: you saved ${formatMoney(saved)}` };
}

