import assert from "node:assert/strict";
import { test } from "node:test";
import { lineTotal, loyaltyDiscount, orderTotal } from "../src/core/price.ts";

test("a line costs its price times its quantity", () => {
  assert.equal(lineTotal({ name: "tea", cents: 450, quantity: 3 }), 1350);
});

test("an order costs the sum of its lines", () => {
  assert.equal(orderTotal([{ name: "tea", cents: 450, quantity: 3 }, { name: "cup", cents: 1200, quantity: 1 }]), 2550);
});

test("an empty order costs nothing", () => {
  assert.equal(orderTotal([]), 0);
});

test("more than five orders earns ten percent off and says how much was saved", () => {
  const lines = [{ name: "tea", cents: 450, quantity: 3 }, { name: "cup", cents: 1200, quantity: 1 }];
  assert.deepEqual(loyaltyDiscount({ id: "c1", orders: 6 }, lines), { total: 2295, saved: 255, message: "Loyalty discount: you saved $2.55" });
});

test("five orders or fewer earns no discount", () => {
  const result = loyaltyDiscount({ id: "c1", orders: 5 }, [{ name: "tea", cents: 1000, quantity: 1 }]);
  assert.equal(result.total, 1000);
  assert.equal(result.saved, 0);
});

